sections.body:
一个联系人有姓名、电话、年龄三样东西。用三个平行数组分开存也能做，但改一条记录要同时改三个地方，一不小心就错位。结构体把它们捆成一个整体，一条记录就是一个变量。

先把下面这段跑起来。

```c
#include <stdio.h>
#include <string.h>

struct Contact {
    char name[20];
    char phone[16];
    int  age;
};

int main(void) {
    struct Contact book[3];

    strcpy(book[0].name, "张伟");
    strcpy(book[0].phone, "13800138000");
    book[0].age = 28;

    strcpy(book[1].name, "李娜");
    strcpy(book[1].phone, "13900139000");
    book[1].age = 34;

    strcpy(book[2].name, "王强");
    strcpy(book[2].phone, "13700137000");
    book[2].age = 22;

    printf("姓名 电话 年龄\n");
    for (int i = 0; i < 3; i++) {
        printf("%s %s %d\n", book[i].name, book[i].phone, book[i].age);
    }
    return 0;
}
```

编译运行的命令还是这一条：

```
gcc -std=c17 -O0 -Wall -Wextra -o prog prog.c -lm
./prog
```

屏幕上出来一张三行的表。关键在 `book[i]`：下标一变，姓名、电话、年龄三个字段一起跟着变，不会串行。下面把这里面的每一步拆开讲。

`struct Contact { ... };` 这句话只是定义了一个新类型，不产生变量，也不占内存。它告诉编译器：以后凡是叫 `struct Contact` 的东西，里面装着一个 20 字节的名字、一个 16 字节的电话和一个整数。

三件事要记住。

- 末尾的分号不能少。漏掉分号时编译器往往把错误报在下一行，看着莫名其妙，先回头检查上一个结构体定义。
- 类型名是两个词 `struct Contact`，不是 `Contact`。想写成一个词要先用 typedef，见 6.5。
- 定义通常放在所有函数外面，这样整个文件都能用。

成员在内存里挨着放，所以一条记录的大小大致等于各成员之和。自己量一下：

```c
#include <stdio.h>

struct Contact {
    char name[20];
    char phone[16];
    int  age;
};

int main(void) {
    struct Contact a;
    printf("一条记录 %zu 字节\n", sizeof a);
    printf("成员加起来 %zu 字节\n", sizeof a.name + sizeof a.phone + sizeof a.age);
    return 0;
}
```

这里两个数相等，都是 40。换一个成员顺序就不一定相等了，编译器为了让 int 落在 4 的整数倍地址上，会在成员之间插几个空字节。所以算内存永远用 sizeof，不要自己把成员大小加起来。

结构体和普通类型一样能组成数组，一个数组就是一整本通讯录。定义时把每条记录各用一对花括号括起来：

```c
struct Contact book[3] = {
    {"张伟", "13800138000", 28},
    {"李娜", "13900139000", 34},
    {"王强", "13700137000", 22},
};
```

遍历就是普通的 for 循环，先取到第 i 条记录，再取它的成员。按姓名查找的完整程序：

```c
#include <stdio.h>
#include <string.h>

struct Contact {
    char name[20];
    char phone[16];
    int  age;
};

int find(struct Contact book[], int n, const char *name) {
    for (int i = 0; i < n; i++) {
        if (strcmp(book[i].name, name) == 0) return i;
    }
    return -1;
}

int main(void) {
    struct Contact book[3] = {
        {"张伟", "13800138000", 28},
        {"李娜", "13900139000", 34},
        {"王强", "13700137000", 22},
    };

    int k = find(book, 3, "李娜");
    if (k >= 0) {
        printf("找到了，%s 的电话是 %s\n", book[k].name, book[k].phone);
    } else {
        printf("没找到\n");
    }
    return 0;
}
```

两个细节。第一，找不到时返回 -1，调用方必须先判一下再用，直接拿 -1 当下标就越界了。第二，数组作参数传的是首地址，函数里不知道有多少条，所以必须额外传一个 n 进去。

每次都写 `struct Contact` 太啰嗦。typedef 给类型起个别名，之后写一个词就行：

```c
typedef struct {
    char name[20];
    char phone[16];
    int  age;
} Contact;

Contact a;
Contact book[100];
```

本课程后面都用这种写法。

有一个例外：结构体里要放指向自己的指针时，必须保留标签名，因为花括号还没结束，别名 Contact 还不存在。

```c
typedef struct Node {
    int value;
    struct Node *next;
} Node;
```

链表就是这么串起来的，第七章会用到。

typedef 只是换个名字，不改变任何行为。`Contact` 和 `struct Contact` 在编译器眼里完全一样。

把结构体传进函数，传进去的是一份复制品，函数里怎么改都影响不到原件。想改原件就传指针。

```c
#include <stdio.h>

typedef struct {
    char name[20];
    int  age;
} Contact;

void birthday_copy(Contact c) { c.age++; }
void birthday_real(Contact *c) { c->age++; }

int main(void) {
    Contact a = {"张伟", 28};

    birthday_copy(a);
    printf("传值之后 %d\n", a.age);

    birthday_real(&a);
    printf("传指针之后 %d\n", a.age);
    return 0;
}
```

输出是 28 和 29。第一次调用改的是副本，函数一返回副本就没了。

通过指针访问成员用箭头，`c->age` 是 `(*c).age` 的简写。两种都对，箭头更常用。

除了能改原件，传指针还省时间。一条记录 40 字节，每次调用都复制一遍并不划算，记录再大一些差别更明显。所以工程里的习惯是结构体一律传指针，只读的加上 const：

```c
void print_contact(const Contact *c) {
    printf("%s %d\n", c->name, c->age);
}
```

加了 const，函数里再想改成员编译器会直接报错，等于给自己上了一道保险。

上一章的 `Contact book[3]` 写死了只能放三条。想放一百条就得改代码重编译，放少了浪费，放多了不够用。动态内存让程序在运行时决定要多大空间。

下面这段先要 2 条的空间，装满了就翻倍，最后装下 5 条。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[20];
    char phone[16];
    int  age;
} Contact;

int main(void) {
    int cap = 2, n = 0;
    Contact *book = malloc(cap * sizeof *book);
    if (book == NULL) {
        printf("内存不够\n");
        return 1;
    }

    const char *names[] = {"张伟", "李娜", "王强", "赵敏", "陈杰"};
    for (int i = 0; i < 5; i++) {
        if (n == cap) {
            cap *= 2;
            Contact *bigger = realloc(book, cap * sizeof *book);
            if (bigger == NULL) { free(book); return 1; }
            book = bigger;
            printf("扩容到 %d 条\n", cap);
        }
        strcpy(book[n].name, names[i]);
        strcpy(book[n].phone, "13800138000");
        book[n].age = 20 + i;
        n++;
    }

    for (int i = 0; i < n; i++) {
        printf("%s %d\n", book[i].name, book[i].age);
    }

    free(book);
    return 0;
}
```

输出里会看到两次扩容，从 2 到 4 再到 8，然后是五条记录。`book` 是一个指针，指向一块运行时申请来的内存，但用起来和数组一模一样，照样写 `book[i].name`。下面把 malloc、realloc、free 三件事分开说。

realloc 把已有的一块内存换成新大小，原来的数据会保留。

```c
Contact *bigger = realloc(book, cap * sizeof *book);
if (bigger == NULL) { free(book); return 1; }
book = bigger;
```

必须用一个新指针接返回值，不能写成 `book = realloc(book, ...)`。因为 realloc 失败时返回 NULL 而原来那块内存还在，如果直接赋给 book，原地址就丢了，那块内存再也 free 不掉。

realloc 可能把数据搬到别的地方，返回的地址和原来不一定相同。所以调用之后，所有指向老地址的指针全部作废，只能用返回的新地址。

扩容策略一般是翻倍，不是每次加一。翻倍的话，装 n 个元素总共只搬几次；每次加一的话每加一个都可能搬一次，数据量大了明显变慢。

realloc 还有两个特殊用法：第一个参数传 NULL 等于 malloc，新大小传 0 等于 free。知道就行，平时分开写更清楚。

动态内存最常出的两类事故，都是往边界外面写。

第一类是下标越界。malloc 申请了 n 个元素，合法下标就是 0 到 n-1。写 `book[n]` 编译器不会报错，运行时也不一定崩，但你已经踩到了别人的内存上。C 不做边界检查，这件事只能靠自己守。

第二类是字符串少留一个字节。C 的字符串结尾必须有一个 `'\0'`，它也占一个字节。所以复制一个长度 5 的字符串，要申请 6 字节：

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    const char *src = "hello";
    char *dst = malloc(strlen(src) + 1);   // 加一是给 '\0' 留的
    if (dst == NULL) return 1;

    strcpy(dst, src);
    printf("%s 长度 %zu\n", dst, strlen(dst));

    free(dst);
    return 0;
}
```

漏掉这个加一，strcpy 会把结束符写到第 6 个字节，正好越界一个。这种错误特别阴险，多数时候程序照跑不误，直到某次那一个字节恰好覆盖了要紧的东西。

加 `-fsanitize=address` 编译能当场抓住这两类问题，写涉及指针的代码时值得顺手带上。

写完一段带 malloc 的代码，照着过一遍：

- malloc 的返回值检查 NULL 了吗
- 申请的字节数是个数乘 sizeof 吗，字符串有没有加一
- 每条返回路径上都 free 了吗，包括中途出错提前 return 的那条
- realloc 用新指针接了吗，失败时老指针 free 了吗
- free 之后还有没有代码用到这个指针
- 下标的范围是不是 0 到 n-1

第三条最容易漏。函数中间有好几个 `return -1`，很容易某一条忘了先 free。一个常用的写法是把出错处理集中到函数末尾：

```c
int work(void) {
    int *a = malloc(100 * sizeof *a);
    if (a == NULL) return -1;

    int rc = -1;
    if (/* 某个条件不满足 */ 0) goto done;
    if (/* 另一个条件不满足 */ 0) goto done;
    rc = 0;

done:
    free(a);
    return rc;
}
```

goto 在别处不建议用，但集中清理资源是它公认合适的场合，标准库和内核里到处都是这种写法。

程序一退出，内存里的数据就没了。要让通讯录下次还在，得写到文件里。

下面这段先把三条记录写进 contacts.txt，再重新打开读回来。

```c
#include <stdio.h>

typedef struct {
    char name[20];
    char phone[16];
    int  age;
} Contact;

int main(void) {
    Contact book[3] = {
        {"张伟", "13800138000", 28},
        {"李娜", "13900139000", 34},
        {"王强", "13700137000", 22},
    };

    FILE *fp = fopen("contacts.txt", "w");
    if (fp == NULL) {
        printf("打不开文件\n");
        return 1;
    }
    for (int i = 0; i < 3; i++) {
        fprintf(fp, "%s %s %d\n", book[i].name, book[i].phone, book[i].age);
    }
    fclose(fp);
    printf("已写入 3 条\n");

    Contact back[10];
    int n = 0;
    fp = fopen("contacts.txt", "r");
    if (fp == NULL) {
        printf("打不开文件\n");
        return 1;
    }
    while (n < 10 && fscanf(fp, "%19s %15s %d",
                            back[n].name, back[n].phone, &back[n].age) == 3) {
        n++;
    }
    fclose(fp);

    printf("读回 %d 条\n", n);
    for (int i = 0; i < n; i++) {
        printf("%s %s %d\n", back[i].name, back[i].phone, back[i].age);
    }
    return 0;
}
```

跑完当前目录会多出一个 contacts.txt，用文本编辑器能直接打开看。程序里的三步是固定套路：fopen 打开并检查，fprintf 或 fscanf 读写，fclose 关闭。下面逐个说。

这两个函数和 printf、scanf 长得一样，只是第一个参数换成了 `FILE *`。

```c
fprintf(fp, "%s %s %d\n", name, phone, age);
fscanf(fp, "%19s %15s %d", name, phone, &age);
```

写的时候格式随意，读的时候格式要能对上，否则读出来的是乱的。所以自己存自己读的文件，最好用固定分隔的简单格式，一行一条记录。

fscanf 的返回值是成功读到的项数。上面那句要读三项，返回 3 才算这一行完整读到了。用它当循环条件，读不满就自然停下：

```c
while (fscanf(fp, "%19s %15s %d", name, phone, &age) == 3) {
    // 处理这一条
}
```

`%19s` 里的 19 限制最多读 19 个字符，加上结束符正好填满 `char name[20]`。不写这个数字，遇到超长的输入就会写出数组之外，这是 C 里最经典的一类漏洞。scanf 家族的 `%s` 一定要带长度限制。

fscanf 的 `%s` 遇到空格就停。所以姓名里带空格的话，一个名字会被切成两半，后面全乱。这时要换成按行读。

fgets 一次读一整行，空格照单全收。

```c
char line[256];
while (fgets(line, sizeof line, fp) != NULL) {
    // line 里是一整行，末尾通常带着换行符
}
```

三个要点。

第一，第二个参数是缓冲区的总大小，包括结束符。写 `sizeof line` 就不会算错。fgets 最多读 size-1 个字符，一定会留位置放结束符，所以它不会越界，比 gets 安全。gets 已经被标准删掉，永远不要用。

第二，读到的内容末尾带着换行符。要去掉的话：

```c
line[strcspn(line, "\n")] = '\0';
```

strcspn 返回第一个换行符的位置，没有换行符就返回整行长度，两种情况这一句都对。

第三，如果一行超过缓冲区，fgets 只读前面一段，剩下的下次再读，末尾就不带换行符。行可能很长时要判断一下有没有读到换行符。

读进来的一整行再自己拆成字段，常用 sscanf，它和 fscanf 一样只是从字符串里读：

```c
int day, high, low;
if (sscanf(line, "%d,%d,%d", &day, &high, &low) == 3) {
    // 三项都读到了
}
```

先 fgets 再 sscanf 是处理文本文件最稳的组合：一行读坏了只影响这一行，不会把后面全带乱。

文本格式人能看懂，但存浮点数会丢精度，解析也慢。二进制格式把结构体原样搬进文件，用 fwrite 和 fread。

```c
FILE *fp = fopen("book.dat", "wb");
fwrite(book, sizeof(Contact), 3, fp);   // 写 3 条，每条 sizeof(Contact) 字节
fclose(fp);

fp = fopen("book.dat", "rb");
int n = (int)fread(back, sizeof(Contact), 10, fp);   // 最多读 10 条，返回实际读到几条
fclose(fp);
```

两个函数的参数一样：数据地址、单条大小、条数、文件指针。返回值都是实际处理的条数，不是字节数。

好处是快，而且不用写解析代码。代价有三个：文件用记事本打开是乱码；换一台机器可能读不出来，因为整数的字节顺序和结构体的对齐方式可能不同；结构体一旦改了字段，老文件全部作废。

所以选哪种看用途。配置文件、日志、要给人看或者要跨机器传的数据用文本；程序自己临时存的大批数据用二进制。这门课后面都用文本，因为出问题时能直接打开文件看，好调试。

通讯录写到现在已经好几百行，全挤在一个文件里，找函数要翻半天。按职责拆开：数据结构和函数声明放头文件，实现放一个源文件，主流程放另一个源文件。

contact.h 只写别人需要知道的东西：

```c
#ifndef CONTACT_H
#define CONTACT_H

typedef struct {
    char name[20];
    char phone[16];
    int  age;
} Contact;

int  contact_find(const Contact *book, int n, const char *name);
void contact_print(const Contact *c);

#endif
```

contact.c 写实现：

```c
#include <stdio.h>
#include <string.h>
#include "contact.h"

int contact_find(const Contact *book, int n, const char *name) {
    for (int i = 0; i < n; i++) {
        if (strcmp(book[i].name, name) == 0) return i;
    }
    return -1;
}

void contact_print(const Contact *c) {
    printf("%s %s %d\n", c->name, c->phone, c->age);
}
```

main.c 只管流程：

```c
#include <stdio.h>
#include "contact.h"

int main(void) {
    Contact book[2] = {
        {"张伟", "13800138000", 28},
        {"李娜", "13900139000", 34},
    };
    int k = contact_find(book, 2, "李娜");
    if (k >= 0) contact_print(&book[k]);
    return 0;
}
```

编译时把两个 .c 都交给 gcc：

```
gcc -std=c17 -O0 -Wall -Wextra -o prog main.c contact.c -lm
```

注意 .h 文件不出现在命令里。头文件不参与编译，它是被 include 进来的，等于把内容原样贴到那一行。

C 自带的库不大，但天天要用的就那么几个头文件。这一章用一个统计小工具把它们串起来。

先跑这段。

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void) {
    char text[] = "The C language is small. The C standard library is not.";

    printf("总长度 %zu\n", strlen(text));

    int letters = 0, spaces = 0;
    for (int i = 0; text[i] != '\0'; i++) {
        if (isalpha((unsigned char)text[i])) letters++;
        else if (isspace((unsigned char)text[i])) spaces++;
    }
    printf("字母 %d 个 空格 %d 个\n", letters, spaces);

    char copy[128];
    snprintf(copy, sizeof copy, "%s", text);
    for (int i = 0; copy[i] != '\0'; i++) {
        copy[i] = (char)tolower((unsigned char)copy[i]);
    }

    int words = 0;
    char longest[32] = "";
    char *p = strtok(copy, " .,");
    while (p != NULL) {
        words++;
        if (strlen(p) > strlen(longest)) snprintf(longest, sizeof longest, "%s", p);
        p = strtok(NULL, " .,");
    }
    printf("单词 %d 个 最长的是 %s\n", words, longest);

    return 0;
}
```

三行输出，一共用到了 strlen、isalpha、isspace、tolower、strtok、snprintf 六个库函数。下面按头文件分类讲。

除了第七章的 malloc 和 free，这个头文件还有几组常用的东西。

字符串转数字：

```c
int   n = atoi("42");          // 转不了就返回 0，分不清是失败还是真的 0
long  m = strtol("42", NULL, 10);   // 更可靠，10 表示十进制
double d = atof("3.14");
```

要判断转换成不成功就用 strtol，它的第二个参数能告诉你停在了哪里：

```c
char *end;
long v = strtol(s, &end, 10);
if (end == s) {
    printf("这不是个数字\n");
}
```

排序用 qsort，它对任何类型都能排，代价是要自己写一个比较函数：

```c
int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

qsort(arr, n, sizeof arr[0], cmp_int);
```

比较函数收两个 `const void *`，要先转成真实类型再解引用。返回负数表示第一个排前面，正数表示第二个排前面，0 表示相等。用 `(x > y) - (x < y)` 而不是 `x - y`，是因为两个很大的整数相减会溢出，结果符号可能反过来。

随机数用 rand，范围是 0 到 RAND_MAX。程序开头调一次 `srand(time(NULL))` 换种子，否则每次运行出的是同一串数。time 在 time.h 里。

另外 `abs` 求整数绝对值，`exit(0)` 直接结束程序，都在这里。

数学函数在 math.h，参数和返回值基本都是 double。

```c
sqrt(x)        // 平方根
pow(x, y)      // x 的 y 次方
fabs(x)        // 浮点数绝对值，整数用 abs
floor(x)       // 向下取整
ceil(x)        // 向上取整
round(x)       // 四舍五入
fmod(x, y)     // 浮点取余，整数的 % 不能用于 double
log(x)         // 自然对数
log10(x)       // 常用对数
sin cos tan    // 三角函数，参数是弧度
```

编译命令末尾的 `-lm` 就是为它准备的。数学库不在默认链接的库里，不加这个参数会报 undefined reference to sqrt。而且它必须写在源文件后面。

一个完整例子，算一组数的标准差：

```c
#include <stdio.h>
#include <math.h>

int main(void) {
    double a[5] = {2.0, 4.0, 4.0, 4.0, 6.0};
    int n = 5;

    double sum = 0.0;
    for (int i = 0; i < n; i++) sum += a[i];
    double mean = sum / n;

    double var = 0.0;
    for (int i = 0; i < n; i++) var += pow(a[i] - mean, 2);
    var /= n;

    printf("平均 %.2f 标准差 %.2f\n", mean, sqrt(var));
    return 0;
}
```

浮点数还有一件事要留心：不要用等号比较两个 double。`0.1 + 0.2 == 0.3` 是假的，因为二进制存不下这些小数。正确做法是看差的绝对值够不够小：

```c
if (fabs(x - y) < 1e-9) { /* 认为相等 */ }
```

先想清楚存什么，再写代码。这一步花的时间最值。

一名学生：

```c
typedef struct {
    int    id;
    char   name[20];
    double chinese;
    double math;
    double english;
} Student;
```

三科分开存而不是用一个 `double score[3]`，是因为后面要按科目名输出，分开写更直白。要是科目数会变，就该用数组加一个科目名表。

平均分不存进结构体，用的时候算：

```c
double avg_of(const Student *s) {
    return (s->chinese + s->math + s->english) / 3.0;
}
```

理由是任何能算出来的字段都不该存。存了就有两份真相，改了成绩忘了更新平均分，两边就对不上了。

一个班：

```c
typedef struct {
    Student *data;   // 堆上的数组
    int      n;      // 已经放了几个
    int      cap;    // 一共能放几个
} Roster;
```

把指针、个数、容量三样捆在一起，是动态数组的标准写法。以后所有函数只要收一个 `Roster *`，不用再传三个参数，也不会出现个数和数组对不上的情况。

容器的生命周期从初始化开始，到释放结束，中间是增删查改。

```c
void roster_init(Roster *r) {
    r->data = NULL;
    r->n = 0;
    r->cap = 0;
}

void roster_free(Roster *r) {
    free(r->data);
    r->data = NULL;
    r->n = 0;
    r->cap = 0;
}
```

初始时指针给 NULL，容量给 0。这样 roster_add 里不用特判第一次，因为 `realloc(NULL, size)` 等价于 malloc。

```c
int roster_add(Roster *r, Student s) {
    if (r->n == r->cap) {
        int cap = (r->cap == 0) ? 4 : r->cap * 2;
        Student *bigger = realloc(r->data, (size_t)cap * sizeof *bigger);
        if (bigger == NULL) return -1;
        r->data = bigger;
        r->cap = cap;
    }
    r->data[r->n++] = s;
    return 0;
}
```

返回 0 表示成功，-1 表示内存不够。调用方该判一下，虽然小程序里基本不会失败。

查找按学号，找不到返回 -1：

```c
int roster_find(const Roster *r, int id) {
    for (int i = 0; i < r->n; i++) {
        if (r->data[i].id == id) return i;
    }
    return -1;
}
```

返回下标而不是返回指针，是因为下标在数组扩容后还有效，指针会失效。这一点在第七章说过，realloc 可能搬家。

排序直接用 qsort，自己写一个按平均分降序的比较函数。

```c
static int by_avg_desc(const void *a, const void *b) {
    double x = avg_of((const Student *)a);
    double y = avg_of((const Student *)b);
    return (y > x) - (y < x);
}

qsort(r.data, (size_t)r.n, sizeof r.data[0], by_avg_desc);
```

比较函数收到的两个指针直接指向 Student，因为数组元素本身就是 Student。降序就是把 x 和 y 的位置反过来写。

统计部分只是几个循环：

```c
double total = 0.0;
int best = 0, fail = 0;
for (int i = 0; i < r.n; i++) {
    total += avg_of(&r.data[i]);
    if (avg_of(&r.data[i]) > avg_of(&r.data[best])) best = i;
    if (r.data[i].chinese < 60 || r.data[i].math < 60 || r.data[i].english < 60) fail++;
}
printf("班级平均 %.2f\n", total / r.n);
```

`r.n` 为 0 时这里会除以零，实际程序要先判一下空。

一个建议：统计和输出分开。统计函数只算数不打印，打印交给另一个函数。这样以后想把结果写进文件而不是屏幕，只改打印那一处。

格式选一行一条，字段用空格分开，姓名不含空格。

```c
int roster_save(const Roster *r, const char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) return -1;
    for (int i = 0; i < r->n; i++) {
        const Student *s = &r->data[i];
        fprintf(fp, "%d %s %.1f %.1f %.1f\n",
                s->id, s->name, s->chinese, s->math, s->english);
    }
    fclose(fp);
    return 0;
}

int roster_load(Roster *r, const char *path) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) return -1;

    char line[128];
    while (fgets(line, sizeof line, fp) != NULL) {
        Student s;
        if (sscanf(line, "%d %19s %lf %lf %lf",
                   &s.id, s.name, &s.chinese, &s.math, &s.english) != 5) continue;
        if (roster_add(r, s) != 0) break;
    }
    fclose(fp);
    return 0;
}
```

三个要点。

第一，读用 fgets 加 sscanf，不直接用 fscanf。这样某一行格式坏了，`continue` 跳过它就行，不会把后面全带乱。

第二，`%19s` 的长度限制不能省，姓名数组是 20 字节。

第三，double 在 scanf 家族里的格式是 `%lf`，不是 `%f`。printf 里两个都行，scanf 里写错就读不进去，这是很常见的一个错。

存盘用 `"w"` 模式，每次覆盖。想追加就用 `"a"`，但那样容易存出重复记录，一般还是整份重写更省心。

把上面几段拼起来，加一段主流程。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int    id;
    char   name[20];
    double chinese;
    double math;
    double english;
} Student;

typedef struct {
    Student *data;
    int      n;
    int      cap;
} Roster;

static double avg_of(const Student *s) {
    return (s->chinese + s->math + s->english) / 3.0;
}

static void roster_init(Roster *r) {
    r->data = NULL; r->n = 0; r->cap = 0;
}

static void roster_free(Roster *r) {
    free(r->data);
    r->data = NULL; r->n = 0; r->cap = 0;
}

static int roster_add(Roster *r, Student s) {
    if (r->n == r->cap) {
        int cap = (r->cap == 0) ? 4 : r->cap * 2;
        Student *bigger = realloc(r->data, (size_t)cap * sizeof *bigger);
        if (bigger == NULL) return -1;
        r->data = bigger;
        r->cap = cap;
    }
    r->data[r->n++] = s;
    return 0;
}

static int roster_find(const Roster *r, int id) {
    for (int i = 0; i < r->n; i++) {
        if (r->data[i].id == id) return i;
    }
    return -1;
}

static int by_avg_desc(const void *a, const void *b) {
    double x = avg_of((const Student *)a);
    double y = avg_of((const Student *)b);
    return (y > x) - (y < x);
}

static int roster_save(const Roster *r, const char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) return -1;
    for (int i = 0; i < r->n; i++) {
        const Student *s = &r->data[i];
        fprintf(fp, "%d %s %.1f %.1f %.1f\n",
                s->id, s->name, s->chinese, s->math, s->english);
    }
    fclose(fp);
    return 0;
}

static int roster_load(Roster *r, const char *path) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) return -1;
    char line[128];
    while (fgets(line, sizeof line, fp) != NULL) {
        Student s;
        if (sscanf(line, "%d %19s %lf %lf %lf",
                   &s.id, s.name, &s.chinese, &s.math, &s.english) != 5) continue;
        if (roster_add(r, s) != 0) break;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    Roster r;
    roster_init(&r);

    Student init[5] = {
        {1001, "张伟", 88.0, 92.5, 79.0},
        {1002, "李娜", 95.0, 88.0, 91.5},
        {1003, "王强", 72.5, 65.0, 58.0},
        {1004, "赵敏", 81.0, 79.5, 85.0},
        {1005, "陈杰", 59.0, 71.0, 66.5},
    };
    for (int i = 0; i < 5; i++) roster_add(&r, init[i]);
    printf("录入 %d 名学生\n", r.n);

    int k = roster_find(&r, 1003);
    if (k >= 0) printf("学号 1003 是 %s 平均 %.2f\n", r.data[k].name, avg_of(&r.data[k]));

    qsort(r.data, (size_t)r.n, sizeof r.data[0], by_avg_desc);
    printf("按平均分排名\n");
    for (int i = 0; i < r.n; i++) {
        printf("%d %s %.2f\n", i + 1, r.data[i].name, avg_of(&r.data[i]));
    }

    double total = 0.0;
    int fail = 0;
    for (int i = 0; i < r.n; i++) {
        total += avg_of(&r.data[i]);
        const Student *s = &r.data[i];
        if (s->chinese < 60 || s->math < 60 || s->english < 60) fail++;
    }
    printf("班级平均 %.2f\n", total / r.n);
    printf("有不及格科目的 %d 人\n", fail);

    roster_save(&r, "scores.txt");
    printf("已存入 scores.txt\n");

    Roster r2;
    roster_init(&r2);
    roster_load(&r2, "scores.txt");
    printf("读回 %d 条 第一条是 %s\n", r2.n, r2.data[0].name);

    roster_free(&r);
    roster_free(&r2);
    return 0;
}
```

跑一遍，五名学生录入、查找、排名、统计、存盘、读回全部走通。班级平均是 78.10，排第一的是李娜。

