#include <stdio.h>

typedef struct {
    double x;
    double y;
} Point;

typedef struct {
    Point  origin;
    double w;
    double h;
} Rect;

double area(Rect r) {
    return r.w * r.h;
}

Point center(Rect r) {
    Point c;
    c.x = r.origin.x + r.w / 2.0;
    c.y = r.origin.y + r.h / 2.0;
    return c;
}

int inside(Rect r, Point p) {
    return p.x >= r.origin.x && p.x <= r.origin.x + r.w
        && p.y >= r.origin.y && p.y <= r.origin.y + r.h;
}

int main(void) {
    Rect r = {{1.0, 2.0}, 4.0, 3.0};

    printf("面积 %.2f\n", area(r));

    Point c = center(r);
    printf("中心 %.2f %.2f\n", c.x, c.y);

