#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *my_dup(const char *s) {
    char *p = malloc(strlen(s) + 1);
    if (p == NULL) return NULL;
    strcpy(p, s);
    return p;
}

char *my_join(const char *a, const char *b, char sep) {
    size_t need = strlen(a) + 1 + strlen(b) + 1;
    char *p = malloc(need);
    if (p == NULL) return NULL;

    char one[2] = {sep, '\0'};
    strcpy(p, a);
    strcat(p, one);
    strcat(p, b);
    return p;
}

int main(void) {
    char *c1 = my_dup("hello");
    char *c2 = my_join("data", "csv", '.');
