        st_push(data[i]);
        printf(" %d", data[i]);
    }
    printf("\n");

    printf("当前元素个数 %d\n", st_size());
    printf("栈顶 %d\n", st_top());

    for (int i = 0; i < 3; i++) {
        printf("弹出 %d\n", st_pop());
    }

    printf("剩下 %d 个\n", st_size());
    printf("栈空 %s\n", st_empty() ? "是" : "否");
    return 0;
}

#define CAP 100

static int buf[CAP];
static int cnt = 0;

void st_push(int v) {
    if (cnt >= CAP) return;
    buf[cnt++] = v;
}

int st_pop(void) {
    if (cnt == 0) return 0;
    return buf[--cnt];
}

int st_top(void) {
    if (cnt == 0) return 0;
    return buf[cnt - 1];
}

int st_size(void) {
    return cnt;
}

int st_empty(void) {
    return cnt == 0;
}

