#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int by_alpha(const void *a, const void *b) {
    const char *x = *(const char * const *)a;
    const char *y = *(const char * const *)b;
    return strcmp(x, y);
}

static int by_length(const void *a, const void *b) {
    const char *x = *(const char * const *)a;
    const char *y = *(const char * const *)b;
    size_t lx = strlen(x), ly = strlen(y);
    if (lx != ly) return (lx > ly) - (lx < ly);
    return strcmp(x, y);
}

static void show(const char *title, const char *w[], int n) {
    printf("%s", title);
    for (int i = 0; i < n; i++) printf(" %s", w[i]);
    printf("\n");
}

int main(void) {
    const char *w[6] = {"banana", "apple", "cherry", "date", "fig", "elderberry"};
    int n = 6;

    qsort(w, n, sizeof w[0], by_alpha);
    show("字典序", w, n);

    qsort(w, n, sizeof w[0], by_length);
    show("长度序", w, n);

    printf("最长的词 %s\n", w[n - 1]);
    return 0;
}

