#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <math.h>

int main(void) {
    const char *s = "温度 23 湿度 65 风速 12 气压 1013 细颗粒物 48";
    int nums[32];
    int n = 0;

    const char *p = s;
    while (*p != '\0' && n < 32) {
        if (isdigit((unsigned char)*p)) {
            char *end;
            long v = strtol(p, &end, 10);
            nums[n++] = (int)v;
            p = end;
        } else {
            p++;
        }
    }

    printf("找到 %d 个数字\n", n);

    int mx = nums[0];
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        if (nums[i] > mx) mx = nums[i];
        sum += nums[i];
    }
    double mean = sum / n;

    double var = 0.0;
    for (int i = 0; i < n; i++) var += pow(nums[i] - mean, 2);
    var /= n;

    printf("最大 %d\n", mx);
    printf("平均 %.2f\n", mean);
    printf("标准差 %.2f\n", sqrt(var));
    return 0;
}

