#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char text[32];
    int  count;
} Word;

typedef struct {
    Word *data;
    int   n;
    int   cap;
} Vocab;

static void vocab_init(Vocab *v) {
    v->data = NULL; v->n = 0; v->cap = 0;
}

static void vocab_free(Vocab *v) {
    free(v->data);
    v->data = NULL; v->n = 0; v->cap = 0;
}

static int vocab_bump(Vocab *v, const char *w) {
    for (int i = 0; i < v->n; i++) {
        if (strcmp(v->data[i].text, w) == 0) {
            v->data[i].count++;
            return 0;
        }
    }
    if (v->n == v->cap) {
        int cap = (v->cap == 0) ? 4 : v->cap * 2;
        Word *bigger = realloc(v->data, (size_t)cap * sizeof *bigger);
        if (bigger == NULL) return -1;
        v->data = bigger;
        v->cap = cap;
    }
    snprintf(v->data[v->n].text, sizeof v->data[v->n].text, "%s", w);
    v->data[v->n].count = 1;
    v->n++;
    return 0;
}

static int by_count_desc(const void *a, const void *b) {
    const Word *x = (const Word *)a;
    const Word *y = (const Word *)b;
    if (x->count != y->count) return y->count - x->count;
    return strcmp(x->text, y->text);
}

int main(void) {
    const char *text[3] = {
        "the quick brown fox jumps over the lazy dog",
        "the dog barks and the fox runs",
        "a quick fox is a happy fox",
    };

    FILE *fp = fopen("words.txt", "w");
    if (fp == NULL) { printf("打不开文件\n"); return 1; }
    for (int i = 0; i < 3; i++) fprintf(fp, "%s\n", text[i]);
    fclose(fp);

    Vocab v;
    vocab_init(&v);
    int total = 0;

    fp = fopen("words.txt", "r");
    if (fp == NULL) { printf("打不开文件\n"); return 1; }

    char line[256];
    while (fgets(line, sizeof line, fp) != NULL) {
        for (int i = 0; line[i] != '\0'; i++) {
            line[i] = (char)tolower((unsigned char)line[i]);
        }
        char *p = strtok(line, " \t\r\n");
        while (p != NULL) {
            total++;
            vocab_bump(&v, p);
            p = strtok(NULL, " \t\r\n");
        }
    }
    fclose(fp);

    qsort(v.data, (size_t)v.n, sizeof v.data[0], by_count_desc);

    printf("总词数 %d\n", total);
    printf("不同词 %d\n", v.n);
    printf("前五名\n");
    int top = v.n < 5 ? v.n : 5;
    for (int i = 0; i < top; i++) {
        printf("%s %d\n", v.data[i].text, v.data[i].count);
    }

    vocab_free(&v);
    return 0;
}
